CREATE OR ALTER PROCEDURE dbo.ContarProductos
    @CategoriaId INT,
    @Cantidad INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @Cantidad = COUNT(*) FROM dbo.Productos WHERE CategoriaId = @CategoriaId;
END;
GO

DECLARE @n INT;
EXEC dbo.ContarProductos @CategoriaId = 1, @Cantidad = @n OUTPUT;
PRINT @n;
DROP PROCEDURE dbo.ContarProductos;

CREATE OR ALTER FUNCTION dbo.PrecioConIva (@Precio DECIMAL(10, 2))
RETURNS DECIMAL(10, 2)
AS
BEGIN
    RETURN ROUND(@Precio * 1.13, 2);
END;
GO

SELECT Nombre, dbo.PrecioConIva(Precio) AS ConIva FROM dbo.Productos;
DROP FUNCTION dbo.PrecioConIva;

CREATE OR ALTER TRIGGER dbo.trg_Clientes_CorreoMinusculas
ON dbo.Clientes
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE c SET Correo = LOWER(c.Correo)
    FROM dbo.Clientes c
    JOIN inserted i ON i.Id = c.Id;
END;
GO

DROP TRIGGER dbo.trg_Clientes_CorreoMinusculas;

